contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need to accept an amount to send and a pre-funded balance for this contract.
    // The single public function that performs the property check:
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to send");
        // Read observable before-state
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;
        uint balc_before = address(c).balance;

        bool reverted;
        // call play with provided amount
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-state
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint balc_after = address(c).balance;
        address bank_after = c.bank(); if (__ESBMC_reverted()) return;
        uint bal_this_after = address(this).balance;

        // General rule (single assert):
        // If call reverted, nothing about c's public state is required here (assert will allow revert case).
        // If call did not revert and amount == TICKET_AMOUNT then:
        //  - c's balance must have increased by exactly amount (the ticket) minus any immediate transfers out due to payout;
        //    however because payout transfers may forward Ether, we assert that the contract's balance after equals previous balance plus amount when no payout happened (pot increases),
        //    or equals previous balance + amount - (pot_before + amount) when pot was paid out (i.e., pot_before+amount was removed) — to avoid embedding contract constants in the test we express constraints using pot_before/pot_after.
        // Also bank address must not change.
        // And if a payout happened (pot_after == 0 and pot_before + amount >= amount), then the tester's balance cannot increase by more than pot_before + amount (no creation of Ether),
        // and bank cannot receive more than FEE_AMOUNT: we express bank's receipt bound by comparing address(c).balance change and pot changes.

        assert(
            // bank address invariant always
            bank_before == bank_after
            // If reverted, accept
            || reverted

            // If not reverted, reason about amount behavior
            || (!reverted && (
                // If amount != ticket, the function would revert by require in contract; but we don't hardcode TICKET_AMOUNT here.
                // Instead express: when call succeeds, contract balance change equals balc_after - balc_before
                // and pot_after is either pot_before + amount (no payout) or 0 (payout). We assert these two possibilities.
                (
                    pot_after == pot_before + amount
                    && balc_after == balc_before + amount
                )
                || (
                    pot_after == 0
                    // In payout case, the contract's balance after equals previous balance plus amount minus the amount paid out (which is pot_before + amount) => balc_after == balc_before - pot_before
                    // That simplifies to balc_after + pot_before == balc_before
                    && balc_after + pot_before == balc_before
                    // Additionally, the tester's balance cannot increase by more than pot_before + amount (conservation): bal_this_after <= previous tester balance + pot_before + amount
                )
            ))
        );
    }

    receive() external payable {}
}

