pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 pot_before;
        try c.pot() returns (uint256 __r) { pot_before = __r; } catch { return; }
        address bank_before;
        try c.bank() returns (address __r) { bank_before = __r; } catch { return; }
        uint balc_before = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 pot_after;
        try c.pot() returns (uint256 __r) { pot_after = __r; } catch { return; }
        uint balc_after = address(c).balance;
        address bank_after;
        try c.bank() returns (address __r) { bank_after = __r; } catch { return; }
        uint bal_this_after = address(this).balance;
        assertTrue(bank_before == bank_after
            // If reverted, accept
            || reverted

            // If not reverted, reason about amount behavior
            || (!reverted && (
                // If amount != ticket, the function would revert by require in contract; but we don't hardcode TICKET_AMOUNT here.
                // Instead express: when call succeeds, contract balance change equals balc_after - balc_before
                // and pot_after is either pot_before + amount (no payout) or 0 (payout). We assert these two possibilities.
                (
                    pot_after == pot_before + amount
                    && balc_after == balc_before + amount
                )
                || (
                    pot_after == 0
                    // In payout case, the contract's balance after equals previous balance plus amount minus the amount paid out (which is pot_before + amount) => balc_after == balc_before - pot_before
                    // That simplifies to balc_after + pot_before == balc_before
                    && balc_after + pot_before == balc_before
                    // Additionally, the tester's balance cannot increase by more than pot_before + amount (conservation): bal_this_after <= previous tester balance + pot_before + amount
                )
            )));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
